function bkcKeep2024(side,j,all,ua){/* pkgBKC (ASK 313, W1 6640, W2 6642, W3 6641): no K-UNX item on an ASSUMES ground when E-ASSUME holds a BOTH NOT STATED fact for the same side and premise and the judge's own ASSUMES clause shares 2 or more content words with that fact, one of them not a proper name. Reads only the Assume Check Record text and the judge's count line (Ruling 383). */try{if(!ua||!(ua.asm||ua.a==='ASSUMES'))return ua;let F=[];try{const a=$('Assume Check Record');if(a&&a.isExecuted)F=(((a.first().json||{}).acx||{}).facts||[]).filter(f=>f&&f.both_not_stated&&f.side===side&&+f.n===+j);}catch(e){F=[];}if(!F.length)return ua;
 const cl=(all||[]).map(z=>[...String(z.seg||'').matchAll(/\bASSUMES\b\s*:?\s*([^]*?)(?=\s+(?:--|—|–)\s+|\bROWS\s+GIVE\b|$)/gi)].map(m=>m[1]).join(' ')).join(' ');if(!cl.trim())return ua;
 const SW=new Set('the and that this with from into unto upon for not are was were his her its their who whom which what when where than then also only both all any one there here have has had been being of to in on at by is be it as or an a he she they them him'.split(' '));
 const ws=t=>{const o=new Map();for(const m of String(t||'').replace(/[’']s\b/g,'').matchAll(/[A-Za-z]+/g)){const w=m[0].toLowerCase();if(w.length<3||SW.has(w))continue;const cap=/^[A-Z]/.test(m[0]);o.set(w,(o.get(w)||false)||cap);}return o;};
 const C=ws(cl);for(const f of F){const W=ws(f.fact);const sh=[...W.keys()].filter(w=>C.has(w));if(sh.length>=2&&sh.some(w=>!W.get(w)&&!C.get(w)))return null;}return ua;}catch(e){return ua;}}
